def graph(workflow):
    jobs = workflow.get("jobs") or {}
    g = {}
    for j, cfg in jobs.items():
        needs = (cfg or {}).get("needs") or []
        if isinstance(needs, str):
            needs = [needs]
        g[j] = list(needs)
    return g


def topo(g):
    indeg = {j: 0 for j in g}
    children = {j: [] for j in g}
    for j, ns in g.items():
        for n in ns:
            if n in g:
                indeg[j] += 1
                children[n].append(j)
    ready = sorted(j for j in g if indeg[j] == 0)
    order = []
    while ready:
        cur = ready.pop(0)
        order.append(cur)
        for ch in sorted(children[cur]):
            indeg[ch] -= 1
            if indeg[ch] == 0:
                ready.append(ch)
        ready.sort()
    if len(order) != len(g):
        return None, sorted(j for j in g if j not in order)
    return order, None


def levels(g):
    """并行层：layer(j) = 1 + max(layer(依赖))，同层任务可并发跑。"""
    memo = {}

    def depth(j):
        if j in memo:
            return memo[j]
        d = 1
        for n in sorted(g[j]):
            if n in g:
                d = max(d, depth(n) + 1)
        memo[j] = d
        return d

    out = {}
    for j in sorted(g):
        out.setdefault(depth(j), []).append(j)
    return out


def critical_path(g):
    memo = {}

    def best(j):
        if j in memo:
            return memo[j]
        cands = [([j], 1)]
        for n in sorted(g[j]):
            if n in g:
                p, d = best(n)
                cands.append((p + [j], d + 1))
        cands.sort(key=lambda x: (-x[1], x[0]))
        memo[j] = cands[0]
        return memo[j]

    top = None
    for r in sorted(g):
        p, d = best(r)
        if top is None or d > top[1] or (d == top[1] and p < top[0]):
            top = (p, d)
    return top


